import type { ReactElement } from 'react';

type IconSlotProps = { children: ReactElement };

export function IconSlot({ children }: IconSlotProps) {
  return children;
}

export const refundIcon = <IconSlot>Refund</IconSlot>;

export function OrdersCount() {
  const { data, isLoading, error } = useQuery({
    queryKey: ['orders'],
    queryFn: ({ signal }) => fetchOrders(signal),
  });
  if (isLoading) {
    return <p>Loading orders…</p>;
  }
  if (error) {
    return <p role="alert">{error.message}</p>;
  }
  return <p>{data.items.length} orders</p>;
}

type LinkProps = { href: string; children: ReactNode };
type ClickProps = { onClick: () => void; children: ReactNode };

export function Action(props: LinkProps | ClickProps) {
  return 'href' in props ? <a href={props.href}>{props.children}</a> : <button type="button" onClick={props.onClick}>{props.children}</button>;
}

export const refund = <Action href="/orders/ord_7f3k" onClick={refundOrder}>Refund</Action>;

export function useDisclosure(initiallyOpen = false) {
  const [isOpen, setIsOpen] = useState(initiallyOpen);
  const toggle = useCallback(() => {
    setIsOpen((open) => !open);
  }, []);
  return [isOpen, toggle];
}

